from pathlib import Path
import json,numpy as np
R=Path(__file__).resolve().parents[2];H=R/'research/round116';rd=lambda p:json.loads(Path(p).read_text())
def main():
 assert rd(H/'SCALAR_AUDIT.json')['n']==768;aa=rd(H/'scores_attempt001/AGGREGATE_ROWS.json');rr=[r for f in (H/'scores_attempt001').glob('*_ALL_ROWS_PRIVATE.json') for r in rd(f)];p='depth_trust_raw_fusedABC';cs=['neither_correct_fusedABC','native_gate_only_fusedABC','wrong_depth_trust_raw_fusedABC','random_GN_trust_raw_fusedABC'];conc=[]
 for c in cs:
  d=np.array([r['arms'][p]['IoU']-r['arms'][c]['IoU'] for r in rr]);conc.append({'control':c,'n':len(d),'gain_pp':float(d.mean()*100),'better':int((d>1e-12).sum()),'worse':int((d< -1e-12).sum()),'same':int((abs(d)<=1e-12).sum()),'largest_positive_single_input_pp':float(max(0,d.max())*100/768),'largest_negative_single_input_pp':float(min(0,d.min())*100/768)})
 rows=[r for r in rr if not r['protected_alias_fallback']];recover=[]
 for k in ['depth_trust_raw','depth_natural_raw','depth_trust_bt','wrong_depth_trust_raw','random_GN_trust_raw']:
  ds=np.array([r['physical_holdout'][k]-r['physical_holdout']['frozen'] for r in rows]);recover.append({'state':k,'n':len(rows),'frozen_holdout_depth_mean':float(np.mean([r['physical_holdout']['frozen'] for r in rows])),'updated_holdout_depth_mean':float(np.mean([r['physical_holdout'][k] for r in rows])),'improved':int((ds< -1e-12).sum()),'worsened':int((ds>1e-12).sum()),'same':int((abs(ds)<=1e-12).sum())})
 for n,x in [('CONCENTRATION_SUMMARY',conc),('RECOVERY_SUMMARY',recover)]: (H/(n+'.json')).write_text(json.dumps(x,indent=2)+'\n')
 lines=['# R116 — 原生grounding基础上的RGB GroupNorm稀疏深度TTA','','本轮不增加source训练或专家，不改变原A256/六层位置/文字视角。沿用既有R91/R76图像编码器及其源域训练的I-only深度头，更新RGB三处GroupNorm的6个仿射张量、224参数；卷积、Adapter、桥、门、late、匹配头、竞争接口和3EED原网络冻结。Point Adapter与早期RGB→point固定旁路，原生点—文字h/u/r不变。','','## 为什么换这个更新位置','','R113真实反向检查证明，原深度项对point_to_image/gateI精确零梯度。因此本轮只取已经存在的深度恢复组件，并把它接到其实际经过的RGB参数；不是再次假定辅助loss下降就等于任务改善。GN不含运行BN统计，不将本实验冒称TENT复现或第一次尝试任何归一化。','','## 监督与预算','','当前A的可见前表面LiDAR经既有标定得到32×48格的log1p(depth)目标；RGB深度头只读图像，不读取点或深度feature，防止直接复制目标。固定哈希75%有效格拟合、25%物理格留出，两遮挡76001/76002保持原定义。拟合前不使用留出目标loss；所有7个参数状态固定后才读取C/融合观测。C是已有对齐LiDAR，当前RGB不变，不称新RGB视角或独立场景。主项一次梯度按原GN参数L2的1%信赖半径归一化；自然clip1/0.5提议为控制。同L2错配train深度目标与随机GN方向为负控制；raw/9尺度回溯均保留，主项不按结果切换。没有目标grounding标签进入梯度/接受。','','## 总体与平台结果','','| 范围 | 方法 | mIoU% | Acc25% | Acc50% |','|---|---|---:|---:|---:|']
 for x in aa:
  if x['arm'].endswith('fusedABC'):lines.append(f"| {x['group']} | {x['arm']} | {x['mIoU_percent']:.6f} | {x['Acc25_percent']:.6f} | {x['Acc50_percent']:.6f} |")
 lines+=['','主项17.286984%，较同信息零步17.265658高0.021325pp，但低于错配深度17.352536和旧单门17.383951，不通过锁定门槛。自然一步17.373861的开发正结果完整保留，不改为主项、不追加步长网格。它也尚未超过已有单门对照。停止当前uniform-depth/GN配方，不据此否定全部物理监督或归一化适应。','','## 恢复和任务分别评价','','```json',json.dumps(recover,indent=2),'```','','```json',json.dumps(conc,indent=2),'```','','恢复误差变化与任务选框收益分开：224参数的更新接口实际有效，不能再归因为深度梯度未到达该scope；但这份恢复监督的任务增量弱。正负IoU尾部均保留，没有新看原图，实例身份UNKNOWN；不把微小同物体框切换自动叫纠错。','','## 额外的loss信息检查','','后验仅CPU前向/反向，未做参数更新或新任务评分：724条中平均15.47%残差处于Huber截断区，正确/错配Huber梯度余弦0.9584；改成MSE后的正确梯度与原Huber余弦0.9958，正确/错配MSE余弦0.9541。因此“多数梯度被Huber截断抹平”的解释不成立，没有继续开MSE loss一轮的依据。保留该阴性分析，不为延长实验换loss。','','## 工程与独立审计','','12真实输入、7状态/输入的完整原生模型与基础缓存重放位等，深度→GN梯度非零；全768含44保护媒体别名冻结回退。31读出共23808任务值，21新16128、10旧7680复用；15204新CPU读出端点、5068实际参数状态核验。CPU还复现了更新后训练深度误差和未拟合物理格误差（最大约1.79e-7），实际写回范数误差5.55e-17、提议误差7.46e-9；概率误差<5e-6、近平0。全部预测先封存，后评分/独立几何和聚合；FINAL未访问。','','## 下一步','','不继续扫描GN层或回归loss。R112静态架构撤回相对原prepared的较大DEV增益尚需扩展验证；下一项固定配置检查原生基础与RGB/竞争接口各自贡献。R115均值/逆向门仅作冻结校准对照，不在扩展数据重新做TTA或据GT选择参数。'];(H/'REPORT.md').write_text('\n'.join(lines)+'\n');print('REPORT116_COMPLETE',flush=True)
if __name__=='__main__':main()
